import sys,numpy as np,mujoco
from scipy.optimize import least_squares
from scipy.spatial.transform import Rotation
sys.path.insert(0,'/opt/tools'); import casa_tool
s=casa_tool.Session();m,d=s.model,s.data; site=m.site('gripper0_right_grip_site').id
ids=[m.joint(f'robot0_joint{i}').id for i in range(1,8)];qa=np.array([m.jnt_qposadr[i] for i in ids]); lim=np.array([m.jnt_range[i] for i in ids]);q=d.qpos[qa].copy();orig=d.qpos.copy();R0=d.site_xmat[site].reshape(3,3).copy()
def solve(t,qprev):
 def f(x):
  d.qpos[qa]=x;mujoco.mj_forward(m,d)
  p=d.site_xpos[site];R=d.site_xmat[site].reshape(3,3)
  return np.r_[p-t,.5*Rotation.from_matrix(R0.T@R).as_rotvec(),.03*(x-qprev)]
 sol=least_squares(f,qprev,bounds=(lim[:,0]+.002,lim[:,1]-.002),max_nfev=150,ftol=1e-8,xtol=1e-8,gtol=1e-8)
 d.qpos[qa]=sol.x;mujoco.mj_forward(m,d)
 return sol.x,np.linalg.norm(f(sol.x)[:6]),d.site_xpos[site].copy()
targs=[]
for y in np.linspace(-2.666,-3.16,11): targs.append(np.array([.907,y,1.31]))
for x in np.linspace(.907,1.12,6)[1:]: targs.append(np.array([x,-3.16,1.31]))
for z in np.linspace(1.31,.70,14)[1:]:targs.append(np.array([1.12,-3.16,z]))
for t in targs:
 q,err,p=solve(t,q); print('t',np.round(t,2),'err',round(err,3),'dq',np.round(q,2),'maxstep')
d.qpos[:]=orig;mujoco.mj_forward(m,d)
